    ("LISN", [], "test", "線路阻抗穩定網路", "傳導 EMI 量測時串在電源線上的標準阻抗網路。", "Line impedance stabilisation network", "The standard impedance network inserted in the supply line for conducted-EMI measurement.", "test.html#bench"),
    ("THB", [], "test", "溫濕度偏壓測試", "85 °C / 85% RH 加偏壓 1000 小時，檢驗濕氣腐蝕。", "Temperature-humidity-bias test", "85 °C / 85% RH with bias for 1000 hours, checking moisture corrosion.", "test.html#qual"),
